      partitionBy: null,  // No partitioning, apply to all documents
      sortBy: { timestamp: 1 },
      output: {
        previousValue: {
          $shift: {
            input: "$value",
            by: 1
          }
        },
        difference: {
          $subtract: [
            "$value",
            "$previousValue"
          ]
        }
      }
    }
  },
  // Step 6: Optional: Exclude the first document (no previous value)
  {
    $match: {
      previousValue: { $ne: null }
    }
  },
  // Step 7: Project the final output
  {
    $project: {
      timestamp: 1,
      value: 1,
      difference: 1
    }
  }
])
```

